import 'dart:async';import 'package:flutter/material.dart';import 'package:video_player/video_player.dart';import 'shell.dart';
class SplashScreen extends StatefulWidget{const SplashScreen({super.key});@override State<SplashScreen> createState()=>_SplashScreenState();}
class _SplashScreenState extends State<SplashScreen>{static const _background=Color(0xFF516E96),_fadeDuration=Duration(milliseconds:350),_revealAnimationAt=Duration(milliseconds:500);VideoPlayerController? _videoController;bool _showStaticLogo=true,_fadingOut=false,_finishing=false;
@override void initState(){super.initState();_startIntroVideo();}
Future<void> _startIntroVideo()async{final c=VideoPlayerController.asset('assets/animation/dukan_9x16_4k.mp4');_videoController=c;try{await c.initialize();if(!mounted){await c.dispose();return;}await c.setLooping(false);await c.setVolume(0);c.addListener(_handleVideoProgress);setState((){});await c.play();}catch(_){c.removeListener(_handleVideoProgress);await c.dispose();if(!mounted)return;_videoController=null;_finishIntro();}}
void _handleVideoProgress(){final c=_videoController;if(c==null||!c.value.isInitialized||_finishing)return;final v=c.value;if(_showStaticLogo&&v.position>=_revealAnimationAt)setState(()=>_showStaticLogo=false);if(v.hasError||(!v.isPlaying&&v.duration>Duration.zero&&v.position>=v.duration-const Duration(milliseconds:100)))_finishIntro();}
Future<void> _finishIntro()async{if(_finishing)return;_finishing=true;_videoController?.removeListener(_handleVideoProgress);if(mounted)setState(()=>_fadingOut=true);await Future.delayed(_fadeDuration);if(!mounted)return;Navigator.of(context).pushReplacement(PageRouteBuilder(transitionDuration:const Duration(milliseconds:350),pageBuilder:(_,__,___)=>const Shell(),transitionsBuilder:(_,a,__,child)=>FadeTransition(opacity:a,child:child)));}
@override void dispose(){_videoController?.removeListener(_handleVideoProgress);_videoController?.dispose();super.dispose();}
@override Widget build(BuildContext context){final c=_videoController;final ready=c?.value.isInitialized??false;return Scaffold(backgroundColor:_background,body:SafeArea(child:Center(child:AnimatedOpacity(opacity:_fadingOut?0:1,duration:_fadeDuration,curve:Curves.easeOut,child:Stack(alignment:Alignment.center,children:[if(c!=null&&c.value.isInitialized)Positioned.fill(child:FittedBox(fit:BoxFit.contain,child:SizedBox(width:c.value.size.width,height:c.value.size.height,child:VideoPlayer(c)))),AnimatedOpacity(opacity:(!ready||_showStaticLogo)?1:0,duration:const Duration(milliseconds:260),curve:Curves.easeInOut,child:Image.asset('assets/images/splash_logo.webp',fit:BoxFit.contain,width:MediaQuery.of(context).size.width*0.72,height:MediaQuery.of(context).size.width*0.72,gaplessPlayback:true))])))));}}
